const webhookData = $('Webhook: Receive CV Application').first().json.body || $('Webhook: Receive CV Application').first().json;
const candidateId = webhookData.candidateId;
const jobTitle = webhookData.jobTitle || 'Chưa rõ chức danh';
const jobDescription = webhookData.jobDescription || '';
const jobRequirements = webhookData.jobRequirements || '';
const cvText = ($json.text || '').trim();

const promptText = `Bạn là Chuyên gia Tuyển dụng Nhân sự cao cấp và Trợ lý AI Đánh giá CV (AI Recruitment Specialist).
Nhiệm vụ của bạn là phân tích CV của ứng viên so với bản mô tả công việc (JD) và các yêu cầu tuyển dụng được cung cấp dưới đây.

=== BẢN MÔ TẢ CÔNG VIỆC ===
- Vị trí: ${jobTitle}
- Mô tả công việc:
${jobDescription}
- Yêu cầu ứng viên:
${jobRequirements}

=== NỘI DUNG CV CỦA ỨNG VIÊN ===
${cvText}

=== HƯỚNG DẪN ĐÁNH GIÁ ===
1. matchScore: Điểm phù hợp của ứng viên từ 0 đến 100 (số thực hoặc số nguyên). Hãy đánh giá công tâm, dựa trên kỹ năng kỹ thuật, kinh nghiệm và độ tương thích với yêu cầu.
2. experienceYears: Số năm kinh nghiệm làm việc ước tính của ứng viên trong ngành/vị trí liên quan (số nguyên >= 0).
3. summary: Nhận xét ngắn gọn, sắc sảo bằng tiếng Việt (khoảng 2-4 câu) nêu rõ điểm mạnh, điểm còn thiếu và mức độ phù hợp tổng thể của ứng viên.
4. parsedSkillsJson: Mảng các kỹ năng cốt lõi (hard skills, soft skills, công nghệ, công cụ) được bóc tách từ CV của ứng viên (mảng chuỗi string).

BẮT BUỘC: Bạn CHỈ ĐƯỢC PHÉP trả về DUY NHẤT một chuỗi JSON thuần (STRICT JSON), KHÔNG kèm bất kỳ lời giải thích nào khác ngoài cấu trúc JSON sau:
{
  "matchScore": 85,
  "experienceYears": 3,
  "summary": "Nhận xét tiếng Việt...",
  "parsedSkillsJson": ["Kỹ năng 1", "Kỹ năng 2"]
}`;

return [{
  json: {
    candidateId,
    promptText
  }
}];

const candidateId = $('Build Gemini Prompt').first().json.candidateId;
const responseJson = $json;

// Trích xuất text từ response Gemini
const rawText = responseJson.candidates?.[0]?.content?.parts?.[0]?.text || '{}';

// Làm sạch markdown nếu có
let cleanedText = rawText.trim();
if (cleanedText.startsWith('```json')) {
  cleanedText = cleanedText.replace(/^```json\s*/, '').replace(/\s*```$/, '');
} else if (cleanedText.startsWith('```')) {
  cleanedText = cleanedText.replace(/^```\s*/, '').replace(/\s*```$/, '');
}

let parsed;
try {
  parsed = JSON.parse(cleanedText);
} catch (e) {
  parsed = {
    matchScore: 0,
    experienceYears: 0,
    summary: "Lỗi phân tích cú pháp từ phản hồi AI: " + e.message,
    parsedSkillsJson: []
  };
}

// Đảm bảo kiểu dữ liệu khớp chính xác với DTO của Backend
let matchScore = typeof parsed.matchScore === 'number' ? parsed.matchScore : (parseFloat(parsed.matchScore) || 0);
if (matchScore > 100) matchScore = 100;
if (matchScore < 0) matchScore = 0;

let experienceYears = typeof parsed.experienceYears === 'number' ? Math.round(parsed.experienceYears) : (parseInt(parsed.experienceYears, 10) || 0);
if (experienceYears < 0) experienceYears = 0;

const summary = typeof parsed.summary === 'string' && parsed.summary.trim().length > 0 
  ? parsed.summary.trim() 
  : "Đã hoàn thành đánh giá hồ sơ ứng viên.";

const parsedSkillsJson = Array.isArray(parsed.parsedSkillsJson) 
  ? parsed.parsedSkillsJson 
  : (typeof parsed.parsedSkillsJson === 'object' && parsed.parsedSkillsJson !== null ? parsed.parsedSkillsJson : []);

return [{
  json: {
    candidateId,
    matchScore,
    experienceYears,
    summary,
    parsedSkillsJson
  }
}];

const webhookData = $('Webhook: Receive CV Application').first().json.body || $('Webhook: Receive CV Application').first().json;
const candidateId = webhookData.candidateId;

return [{
  json: {
    candidateId,
    matchScore: 0,
    experienceYears: 0,
    summary: "CV trống hoặc không đọc được nội dung văn bản (file PDF dạng ảnh scan hoặc không có chữ).",
    parsedSkillsJson: []
  }
}];
